"use client";

import { useEffect, useMemo, useState } from "react";
import { systemNow } from "../lib/exam";
import { getRecord, putRecord } from "../lib/indexed-db";
import {
  buildWalkthroughOutline,
  emptyPortfolioDraft,
  walkthroughCompleteness,
  type PortfolioDraft,
} from "../lib/portfolio";
import type { StoredRecord } from "../lib/models";

type PortfolioRecord = StoredRecord & {
  draft: PortfolioDraft;
  translationNote: string;
  reusePhrase: string;
  savedAt: number;
};

const FIELDS: Array<{ key: keyof PortfolioDraft; label: string; prompt: string }> = [
  { key: "project", label: "Project + purpose", prompt: "What did you make, and why did it exist?" },
  { key: "audience", label: "Audience", prompt: "Who needed it? Be specific." },
  { key: "painPoint", label: "User pain point", prompt: "What observable problem were people facing?" },
  { key: "role", label: "Your role", prompt: "What exactly did you own or contribute?" },
  { key: "choices", label: "Design choices", prompt: "What did you choose, reject, and why?" },
  { key: "system", label: "Design system", prompt: "Which rules or components kept it consistent?" },
  { key: "iteration", label: "Iteration", prompt: "What changed after feedback or testing?" },
  { key: "impact", label: "Impact", prompt: "What changed, or what would you measure next?" },
  { key: "nextRole", label: "Role fit", prompt: "Which target role does this evidence support?" },
];

function formatTimer(seconds: number): string {
  return `${String(Math.floor(seconds / 60)).padStart(2, "0")}:${String(seconds % 60).padStart(2, "0")}`;
}

export function PortfolioWalkthrough() {
  const [draft, setDraft] = useState<PortfolioDraft>(emptyPortfolioDraft());
  const [translationNote, setTranslationNote] = useState("");
  const [reusePhrase, setReusePhrase] = useState("");
  const [saveState, setSaveState] = useState("Checking this device…");
  const [timerMode, setTimerMode] = useState<60 | 300>(60);
  const [seconds, setSeconds] = useState(60);
  const [running, setRunning] = useState(false);

  useEffect(() => {
    let active = true;
    void getRecord<PortfolioRecord>("portfolio", "primary-case-study")
      .then((record) => {
        if (!active) return;
        if (record) { setDraft(record.draft); setTranslationNote(record.translationNote); setReusePhrase(record.reusePhrase); }
        setSaveState("Saved on this device");
      })
      .catch(() => { if (active) setSaveState("Device saving unavailable"); });
    return () => { active = false; };
  }, []);

  useEffect(() => {
    if (!running) return;
    const timer = window.setInterval(() => {
      setSeconds((current) => {
        if (current <= 1) { window.clearInterval(timer); setRunning(false); return 0; }
        return current - 1;
      });
    }, 1_000);
    return () => window.clearInterval(timer);
  }, [running]);

  const outline = useMemo(() => buildWalkthroughOutline(draft), [draft]);
  const completeness = walkthroughCompleteness(draft);

  async function persist(nextDraft: PortfolioDraft, nextTranslation = translationNote, nextPhrase = reusePhrase) {
    setSaveState("Saving…");
    try {
      await putRecord("portfolio", { id: "primary-case-study", draft: nextDraft, translationNote: nextTranslation, reusePhrase: nextPhrase, savedAt: systemNow() });
      setSaveState("Saved on this device");
    } catch { setSaveState("Device saving unavailable"); }
  }

  function updateField(key: keyof PortfolioDraft, value: string) {
    const next = { ...draft, [key]: value };
    setDraft(next);
    void persist(next);
  }

  function chooseTimer(mode: 60 | 300) {
    setTimerMode(mode);
    setSeconds(mode);
    setRunning(false);
  }

  return (
    <section className="portfolio-workspace">
      <div className="portfolio-editor">
        <div className="portfolio-status"><div><span>Case evidence</span><strong>{completeness.completed} / {completeness.total}</strong></div><div className="portfolio-progress"><span style={{ width: `${(completeness.completed / completeness.total) * 100}%` }} /></div><span role="status">{saveState}</span></div>
        <div className="portfolio-fields">
          {FIELDS.map((field, index) => (
            <label className="portfolio-field" key={field.key}>
              <span><b>{String(index + 1).padStart(2, "0")}</b>{field.label}</span>
              <textarea value={draft[field.key]} onChange={(event) => updateField(field.key, event.target.value)} placeholder={field.prompt} rows={3} />
            </label>
          ))}
        </div>
      </div>

      <aside className="walkthrough-preview">
        <div className="rehearsal-controls">
          <div><button className={timerMode === 60 ? "is-active" : ""} type="button" onClick={() => chooseTimer(60)}>60 sec</button><button className={timerMode === 300 ? "is-active" : ""} type="button" onClick={() => chooseTimer(300)}>5 min</button></div>
          <strong>{formatTimer(seconds)}</strong>
          <button className="rehearse-button" type="button" onClick={() => setRunning((value) => !value)}>{running ? "Pause" : seconds === 0 ? "Reset" : "Rehearse"}</button>
        </div>
        <div className="outline-list">
          {outline.map((section, index) => (
            <article key={section.label}><span>{String(index + 1).padStart(2, "0")}</span><div><p>{section.label}</p><strong>{section.englishLead}</strong><small>{section.content}</small></div></article>
          ))}
        </div>
        <div className="reflection-box">
          <label><span>Where did I translate from Chinese?</span><textarea rows={2} value={translationNote} onChange={(event) => { const value = event.target.value; setTranslationNote(value); void persist(draft, value, reusePhrase); }} /></label>
          <label><span>Which phrase will I reuse?</span><input value={reusePhrase} onChange={(event) => { const value = event.target.value; setReusePhrase(value); void persist(draft, translationNote, value); }} /></label>
        </div>
      </aside>
    </section>
  );
}

app/components/practice-studio.tsx:
"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { getAiStatus, requestAi } from "../lib/ai-client";
import { validateSpeakingFeedback, validateWritingFeedback, type SpeakingFeedback, type WritingFeedback } from "../lib/ai-contracts";
import { putRecord } from "../lib/indexed-db";

export function PracticeStudio({ kind }: { kind: "writing" | "speaking" }) {
  const writing = kind === "writing";
  const [prompt, setPrompt] = useState(writing ? "Describe a design decision that improved clarity for the user." : "Explain one project choice and the trade-off behind it.");
  const [response, setResponse] = useState("");
  const [taskType, setTaskType] = useState<"ielts" | "work" | "general">(writing ? "ielts" : "work");
  const [status, setStatus] = useState("AI NOT CONNECTED");
  const [writingFeedback, setWritingFeedback] = useState<WritingFeedback | null>(null);
  const [speakingFeedback, setSpeakingFeedback] = useState<SpeakingFeedback | null>(null);
  const [recording, setRecording] = useState(false);
  const recorder = useRef<MediaRecorder | null>(null);
  const stream = useRef<MediaStream | null>(null);
  const wordCount = useMemo(() => response.trim() ? response.trim().split(/\s+/).length : 0, [response]);

  useEffect(() => {
    let active = true;
    void getAiStatus().then((aiStatus) => {
      if (!active) return;
      setStatus(aiStatus.configured ? `AI READY · ${aiStatus.providers.map((provider) => provider.toUpperCase()).join(" / ")}` : "AI NOT CONNECTED");
    });
    return () => { active = false; };
  }, []);

  async function save() {
    await putRecord(writing ? "writing-practice" : "speaking-practice", { id: `${kind}-${Date.now()}`, prompt, response, taskType, updatedAt: Date.now() });
    setStatus("SAVED ON THIS DEVICE");
  }

  async function feedback() {
    if (!response.trim()) { setStatus(writing ? "WRITE A RESPONSE FIRST" : "ADD A TRANSCRIPT FIRST"); return; }
    setStatus("CHECKING…");
    const result = writing
      ? await requestAi<WritingFeedback>({ capability: "writing-feedback", prompt, response, taskType })
      : await requestAi<SpeakingFeedback>({ capability: "speaking-feedback", prompt, transcript: response, audioAnalyzed: false });
    if (!result.ok) { setStatus(result.message); return; }
    if (writing && validateWritingFeedback(result.data)) { setWritingFeedback(result.data); setStatus("UNOFFICIAL FEEDBACK READY"); return; }
    if (!writing && validateSpeakingFeedback(result.data)) { setSpeakingFeedback(result.data); setStatus("UNOFFICIAL FEEDBACK READY"); return; }
    setStatus("INVALID AI RESPONSE — YOUR DRAFT IS UNCHANGED");
  }

  async function toggleRecording() {
    if (recording) {
      recorder.current?.stop();
      stream.current?.getTracks().forEach((track) => track.stop());
      setRecording(false);
      setStatus("RECORDING STOPPED — TYPE OR PASTE THE TRANSCRIPT BELOW");
      return;
    }
    if (!navigator.mediaDevices?.getUserMedia || typeof MediaRecorder === "undefined") { setStatus("RECORDING UNAVAILABLE — USE THE TRANSCRIPT BOX"); return; }
    try {
      stream.current = await navigator.mediaDevices.getUserMedia({ audio: true });
      recorder.current = new MediaRecorder(stream.current);
      recorder.current.start();
      setRecording(true);
      setStatus("RECORDING… AUDIO STAYS IN THIS BROWSER SESSION");
    } catch { setStatus("MICROPHONE ACCESS WAS NOT AVAILABLE"); }
  }

  return (
    <section className="practice-studio">
      <header className="studio-status"><span>{writing ? "WRITING" : "SPEAKING"} / DEVICE-LOCAL</span><strong>{status}</strong></header>
      <div className="studio-grid">
        <div className="studio-editor">
          <label><span>PROMPT</span><textarea rows={3} value={prompt} onChange={(event) => setPrompt(event.target.value)} /></label>
          {writing && <label><span>TASK TYPE</span><select value={taskType} onChange={(event) => setTaskType(event.target.value as typeof taskType)}><option value="ielts">IELTS-style</option><option value="work">International work</option><option value="general">General</option></select></label>}
          {!writing && <button className="record-button" type="button" onClick={() => void toggleRecording()}>{recording ? "STOP RECORDING" : "RECORD A PRACTICE TAKE"}</button>}
          <label><span>{writing ? "YOUR DRAFT" : "TRANSCRIPT"}</span><textarea className="practice-response" rows={14} value={response} onChange={(event) => setResponse(event.target.value)} placeholder={writing ? "Write here. Your draft remains even if AI feedback fails." : "Type or paste what you said. Transcript-only feedback never claims pronunciation analysis."} /></label>
          <div className="studio-actions"><span>{wordCount} WORDS</span><button type="button" onClick={() => void save()}>SAVE</button><button type="button" onClick={() => void feedback()}>GET AI FEEDBACK ↗</button></div>
        </div>
        <aside className="feedback-panel">
          <p>UNOFFICIAL PRACTICE FEEDBACK</p>
          {!writingFeedback && !speakingFeedback && <div className="feedback-empty"><strong>{status}</strong><span>Your prompt and response can still be written and saved on this device.</span></div>}
          {writingFeedback && <><h2>Unofficial estimate</h2><p>{writingFeedback.bandRange ?? "Not scored for this task type"}</p><h2>What works</h2>{writingFeedback.criteria.map((item) => <p key={item.heading}><strong>{item.heading}</strong> {item.observation}</p>)}<h2>Priority corrections</h2>{writingFeedback.corrections.map((item) => <p key={item.original}>{item.original} → {item.revision}<br /><small>{item.explanation}</small></p>)}<h2>Next practice</h2><ul>{writingFeedback.nextActions.map((item) => <li key={item}>{item}</li>)}</ul></>}
          {speakingFeedback && <><h2>Fluency and clarity</h2>{speakingFeedback.observations.map((item) => <p key={item}>{item}</p>)}<h2>Vocabulary and grammar</h2><p>Review the alternatives below and keep only the ones that sound like you.</p><h2>Natural alternatives</h2><ul>{speakingFeedback.alternatives.map((item) => <li key={item}>{item}</li>)}</ul><h2>Next attempt</h2><p>{speakingFeedback.nextAttempt}</p></>}
        </aside>
      </div>
    </section>
  );
}

app/components/seed-library.tsx:
"use client";

import { useMemo, useState } from "react";
import { putRecord } from "../lib/indexed-db";
import { SEED_LIBRARY, type SeedActivity, type SeedCategory } from "../lib/seeds";
import { systemNow } from "../lib/exam";

const CATEGORIES: Array<"All" | SeedCategory> = ["All", "Design", "Work", "Life", "Culture", "Academic"];

export function SeedLibrary() {
  const [category, setCategory] = useState<"All" | SeedCategory>("All");
  const [level, setLevel] = useState("All");
  const [minutes, setMinutes] = useState("All");
  const [query, setQuery] = useState("");
  const [selected, setSelected] = useState<SeedActivity | null>(null);
  const [saved, setSaved] = useState<string[]>([]);
  const [saveMessage, setSaveMessage] = useState("");

  const results = useMemo(() => SEED_LIBRARY.filter((item) => {
    const haystack = `${item.title} ${item.publisher} ${item.skills.join(" ")}`.toLowerCase();
    return (category === "All" || item.category === category)
      && (level === "All" || item.level === level)
      && (minutes === "All" || item.minutes === Number(minutes))
      && haystack.includes(query.trim().toLowerCase());
  }), [category, level, minutes, query]);

  async function saveItem(item: SeedActivity) {
    try {
      await putRecord("library", { id: item.id, savedAt: systemNow() });
      setSaved((current) => current.includes(item.id) ? current : [...current, item.id]);
      setSaveMessage("Saved on this device");
    } catch { setSaveMessage("Could not save on this device"); }
  }

  return (
    <section className="library-layout">
      <div className="library-main">
        <div className="library-filters">
          <div className="category-chips" aria-label="Content category">
            {CATEGORIES.map((item) => <button className={category === item ? "is-active" : ""} key={item} type="button" onClick={() => setCategory(item)}>{item}</button>)}
          </div>
          <div className="filter-row">
            <label className="search-field"><span className="sr-only">Search activities</span><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search topics or skills" /></label>
            <label><span className="sr-only">Level</span><select value={level} onChange={(event) => setLevel(event.target.value)}><option>All</option><option>B1</option><option>B2</option><option>C1</option></select></label>
            <label><span className="sr-only">Duration</span><select value={minutes} onChange={(event) => setMinutes(event.target.value)}><option>All</option><option value="5">5 min</option><option value="15">15 min</option><option value="30">30 min</option></select></label>
          </div>
        </div>

        <div className="library-count"><span>{results.length} activities</span><span>Publisher-hosted sources</span></div>
        <div className="seed-grid">
          {results.map((item, index) => (
            <article className="seed-card" key={item.id}>
              <div className="seed-top"><span>{String(index + 1).padStart(2, "0")}</span><span>{item.minutes} MIN</span></div>
              <div><p>{item.category} · {item.level}</p><h2>{item.title}</h2><span className="publisher">{item.publisher}</span></div>
              <div className="skill-list">{item.skills.map((skill) => <span key={skill}>{skill}</span>)}</div>
              <div className="seed-actions"><button type="button" onClick={() => setSelected(item)}>View activity</button><button className={saved.includes(item.id) ? "is-saved" : ""} type="button" onClick={() => void saveItem(item)}>{saved.includes(item.id) ? "Saved" : "Save"}</button></div>
            </article>
          ))}
        </div>
      </div>

      <aside className={selected ? "activity-drawer is-open" : "activity-drawer"} aria-label="Activity details">
        {selected ? (
          <>
            <button className="drawer-close" type="button" onClick={() => setSelected(null)} aria-label="Close activity">×</button>
            <span className="source-label">{selected.category} · {selected.level} · {selected.minutes} MIN</span>
            <h2>{selected.title}</h2>
            <p className="drawer-publisher">{selected.publisher}</p>
            <div className="activity-step"><span>01</span><div><strong>Before you open it</strong><p>{selected.prompt}</p></div></div>
            <div className="activity-step"><span>02</span><div><strong>Your required output</strong><p>{selected.output}</p></div></div>
            <div className="rights-note"><strong>Usage note</strong><p>{selected.usageBasis}</p><small>Reviewed {selected.reviewedAt}</small></div>
            <a className="primary-action source-action" href={selected.sourceUrl} target="_blank" rel="noreferrer">Open on publisher site ↗</a>
            <button className="secondary-action" type="button" onClick={() => void saveItem(selected)}>Save activity</button>
            <p className="drawer-status" role="status">{saveMessage}</p>
          </>
        ) : (
          <div className="drawer-empty"><span>↗</span><p>选择一个素材，查看专门为它设计的输入与输出练习。</p></div>
        )}
      </aside>
    </section>
  );
}

app/components/today-board.tsx:
"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { getRecord, isIndexedDbAvailable, putRecord } from "../lib/indexed-db";
import type { PlanMode, StoredRecord, TodayTask } from "../lib/models";
import { buildTodayPlan } from "../lib/today";
import { getAiStatus, requestAi } from "../lib/ai-client";
import { validateGeneratedPlan, type GeneratedPlan } from "../lib/ai-contracts";

type PreferenceRecord = StoredRecord & { value: PlanMode };
type TodayRecord = StoredRecord & { completed: string[] };

const MODES: Array<{ value: PlanMode; label: string }> = [
  { value: 10, label: "Low energy" },
  { value: 45, label: "Normal" },
  { value: 90, label: "Immersive" },
];

const ALTERNATES: Record<number, Pick<TodayTask, "title" | "detail">[]> = {
  5: [
    { title: "Five useful phrases", detail: "挑五个真正会用到的表达，各说一句。" },
    { title: "Tiny retell", detail: "用五分钟复述刚看过的一小段英文内容。" },
  ],
  10: [
    { title: "Role requirement scan", detail: "读一份岗位描述，圈出三个重复要求。" },
    { title: "Impact sentence", detail: "把一个作品成果写成清楚、不过度夸张的英文句子。" },
  ],
  15: [
    { title: "Question-type repair", detail: "只练一种雅思题型并记录定位依据。" },
    { title: "Design talk notes", detail: "听一段设计演讲，留下三条英文笔记。" },
  ],
  20: [
    { title: "Think in English loop", detail: "同一个设计想法分别讲 30 秒、60 秒和 2 分钟。" },
  ],
  25: [
    { title: "Deep input + output", detail: "完成一段输入，再做两分钟英文总结。" },
  ],
};

function localDateKey(): string {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, "0");
  const day = String(now.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

export function TodayBoard() {
  const [mode, setMode] = useState<PlanMode>(45);
  const [completed, setCompleted] = useState<string[]>([]);
  const [replacements, setReplacements] = useState<Record<string, number>>({});
  const [ready, setReady] = useState(false);
  const [saveState, setSaveState] = useState<"loading" | "saved" | "saving" | "unavailable">("loading");
  const [aiTasks, setAiTasks] = useState<TodayTask[] | null>(null);
  const [reshapeState, setReshapeState] = useState("AI NOT CONNECTED");
  const dayId = `today-${localDateKey()}`;
  const baseTasks = useMemo(() => buildTodayPlan(mode), [mode]);
  const tasks = (aiTasks ?? baseTasks).map((task) => {
    const alternatives = ALTERNATES[task.minutes] ?? [];
    const index = replacements[task.id];
    return index === undefined || alternatives.length === 0
      ? task
      : { ...task, ...alternatives[index % alternatives.length] };
  });

  useEffect(() => {
    let active = true;
    void getAiStatus().then((status) => {
      if (!active) return;
      setReshapeState(status.configured ? `AI READY · ${status.providers.map((provider) => provider.toUpperCase()).join(" / ")}` : "AI NOT CONNECTED");
    });
    async function restore() {
      if (!(await isIndexedDbAvailable())) {
        if (active) { setSaveState("unavailable"); setReady(true); }
        return;
      }
      const [preference, today] = await Promise.all([
        getRecord<PreferenceRecord>("preferences", "plan-mode"),
        getRecord<TodayRecord>("today", dayId),
      ]);
      if (!active) return;
      if (preference?.value === 10 || preference?.value === 45 || preference?.value === 90) setMode(preference.value);
      if (today?.completed) setCompleted(today.completed);
      setSaveState("saved");
      setReady(true);
    }
    void restore().catch(() => { if (active) { setSaveState("unavailable"); setReady(true); } });
    return () => { active = false; };
  }, [dayId]);

  async function selectMode(nextMode: PlanMode) {
    setMode(nextMode);
    setCompleted([]);
    setReplacements({});
    setAiTasks(null);
    if (saveState === "unavailable") return;
    setSaveState("saving");
    try {
      await Promise.all([
        putRecord("preferences", { id: "plan-mode", value: nextMode }),
        putRecord("today", { id: dayId, completed: [] }),
      ]);
      setSaveState("saved");
    } catch { setSaveState("unavailable"); }
  }

  async function reshapeWithAi() {
    setReshapeState("RESHAPING…");
    const result = await requestAi<GeneratedPlan>({ capability: "daily-plan", minutes: mode, focus: "balanced IELTS and international work English", evidence: [] });
    if (!result.ok) { setReshapeState(result.message); return; }
    if (!validateGeneratedPlan(result.data, mode)) { setReshapeState("INVALID PLAN — ORIGINAL KEPT"); return; }
    setAiTasks(result.data.tasks);
    setReshapeState("AI PLAN READY");
    try { await putRecord("generated-plans", { id: dayId, tasks: result.data.tasks, createdAt: Date.now() }); } catch { /* The plan remains usable for this session. */ }
  }

  async function toggleTask(taskId: string) {
    const next = completed.includes(taskId)
      ? completed.filter((id) => id !== taskId)
      : [...completed, taskId];
    setCompleted(next);
    if (saveState === "unavailable") return;
    setSaveState("saving");
    try {
      await putRecord("today", { id: dayId, completed: next });
      setSaveState("saved");
    } catch { setSaveState("unavailable"); }
  }

  function replaceTask(task: TodayTask) {
    const alternatives = ALTERNATES[task.minutes] ?? [];
    if (alternatives.length === 0) return;
    setReplacements((current) => ({ ...current, [task.id]: ((current[task.id] ?? -1) + 1) % alternatives.length }));
  }

  const completedCount = tasks.filter((task) => completed.includes(task.id)).length;
  const progress = tasks.length ? Math.round((completedCount / tasks.length) * 100) : 0;

  return (
    <section className="today-board" aria-busy={!ready}>
      <div className="today-toolbar">
        <div className="mode-switcher" aria-label="Daily plan length">
          {MODES.map((item) => (
            <button className={mode === item.value ? "mode-button is-selected" : "mode-button"}
              key={item.value} type="button" onClick={() => void selectMode(item.value)}>
              <strong>{item.value}</strong><span>{item.label}</span>
            </button>
          ))}
        </div>
        <div className={`save-indicator ${saveState}`} role="status">
          <span aria-hidden="true">{saveState === "saved" ? "●" : "○"}</span>
          {saveState === "loading" && "Checking this device…"}
          {saveState === "saving" && "Saving…"}
          {saveState === "saved" && "Saved on this device"}
          {saveState === "unavailable" && "Device saving unavailable"}
        </div>
        <button className="reshape-button" type="button" onClick={() => void reshapeWithAi()}>RESHAPE WITH AI</button>
        <span className="reshape-state" role="status">{reshapeState}</span>
      </div>

      {saveState === "unavailable" && (
        <div className="storage-warning" role="alert">当前浏览器无法使用 IndexedDB。你仍可查看计划，但刷新后完成状态不会保留。</div>
      )}

      <div className="progress-row">
        <div><span>Today</span><strong>{completedCount} / {tasks.length}</strong></div>
        <div className="progress-track" aria-label={`${progress}% complete`}><span style={{ width: `${progress}%` }} /></div>
        <span>{progress}%</span>
      </div>

      <div className="task-list">
        {tasks.map((task, index) => {
          const done = completed.includes(task.id);
          return (
            <article className={`task-card accent-${task.accent} ${done ? "is-done" : ""}`} key={task.id}>
              <button className="task-check" type="button" onClick={() => void toggleTask(task.id)} aria-pressed={done} aria-label={`${done ? "Mark incomplete" : "Mark complete"}: ${task.title}`}>
                {done ? "✓" : String(index + 1).padStart(2, "0")}
              </button>
              <div className="task-copy"><span>{task.module}</span><h2>{task.title}</h2><p>{task.detail}</p><Link className="task-open" href={task.href}>OPEN PRACTICE ↗</Link></div>
              <div className="task-meta"><strong>{task.minutes}</strong><span>MIN</span><button type="button" onClick={() => replaceTask(task)}>换一个</button></div>
            </article>
          );
        })}
      </div>
    </section>
  );
}

