app/globals.css:
@import "tailwindcss";

:root {
  --paper: #fafafa;
  --paper-strong: #ffffff;
  --ink: #171717;
  --muted: #666666;
  --line: #d8d8d8;
  --blue: #566f83;
  --blue-deep: #334b5c;
  --coral: #df7d68;
  --sage: #a7b5a4;
  --shadow: 0 18px 50px rgba(31, 41, 45, 0.08);
}

* { box-sizing: border-box; min-width: 0; }
html { max-width: 100%; overflow-x: clip; background: var(--paper); color: var(--ink); }
body {
  max-width: 100%;
  overflow-x: clip;
  min-height: 100vh;
  margin: 0;
  background: radial-gradient(circle at 82% 12%, rgba(223,125,104,.09), transparent 22rem), linear-gradient(135deg, rgba(86,111,131,.04), transparent 42%), var(--paper);
  color: var(--ink);
  font-family: "Segoe UI", Arial, Helvetica, sans-serif;
  line-height: 1.5;
}
img, video, iframe { max-width: 100%; }
a { color: inherit; text-decoration: none; }
button, input, textarea, select { color: inherit; font: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }
:focus-visible { outline: 3px solid rgba(223,125,104,.72); outline-offset: 3px; }

.app-frame { display: grid; grid-template-columns: 250px minmax(0,1fr); min-height: 100vh; }
.side-rail { position: sticky; top: 0; display: flex; flex-direction: column; height: 100vh; padding: 32px 22px 24px; border-right: 1px solid var(--line); background: rgba(255,253,247,.72); }
.brand { display: flex; align-items: center; gap: 12px; min-height: 48px; letter-spacing: .18em; }
.brand span:last-child { display: grid; line-height: 1.08; }
.brand strong { font-family: Georgia, "Times New Roman", serif; font-size: 16px; }
.brand-orbit { display: grid; width: 36px; height: 36px; place-items: center; border: 1px solid var(--ink); border-radius: 50%; font-size: 22px; }
.main-nav { display: grid; gap: 5px; margin-top: 54px; }
.nav-link { display: grid; grid-template-columns: 32px 1fr; align-items: center; min-height: 46px; padding: 0 12px; border-radius: 12px; color: var(--muted); font-size: 14px; font-weight: 600; transition: background 160ms ease, color 160ms ease, transform 160ms ease; }
.nav-link:hover { color: var(--ink); transform: translateX(2px); }
.nav-link.is-active { background: var(--ink); color: var(--paper-strong); }
.nav-mark { font-family: Georgia, "Times New Roman", serif; font-size: 11px; opacity: .62; }
.account-card { display: grid; grid-template-columns: 38px 1fr 28px; align-items: center; gap: 10px; margin-top: auto; padding-top: 20px; border-top: 1px solid var(--line); }
.avatar { display: grid; width: 38px; height: 38px; place-items: center; border-radius: 50%; background: var(--blue); color: white; font-family: Georgia, "Times New Roman", serif; font-size: 12px; }
.account-copy { display: grid; min-width: 0; }
.account-copy strong, .account-copy small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.account-copy strong { font-size: 13px; }
.account-copy small { color: var(--muted); font-size: 11px; }
.sign-out { display: grid; min-width: 44px; min-height: 44px; place-items: center; color: var(--muted); }
.main-canvas { width: min(100%,1480px); padding: 42px clamp(24px,4vw,72px) 72px; }
.page-heading { display: flex; align-items: flex-end; justify-content: space-between; gap: 32px; margin-bottom: 40px; }
.page-heading h1 { max-width: 780px; margin: 7px 0 14px; font-family: Georgia, "Times New Roman", serif; font-size: clamp(42px,6vw,76px); font-weight: 400; letter-spacing: -.045em; line-height: .98; }
.eyebrow, .section-kicker { margin: 0; color: var(--blue-deep); font-size: 11px; font-weight: 700; letter-spacing: .19em; text-transform: uppercase; }
.lede { max-width: 700px; margin: 0; color: var(--muted); font-size: 16px; }
.script-line { margin: 0 12px 2px 0; color: var(--coral); font-family: "Segoe Script", "Bradley Hand", cursive; font-size: clamp(20px,2.3vw,32px); transform: rotate(-3deg); white-space: nowrap; }
.placeholder-board, .deferred-card { border: 1px solid var(--line); background: rgba(255,253,247,.75); box-shadow: var(--shadow); }
.placeholder-board { min-height: 320px; padding: clamp(28px,5vw,64px); border-radius: 24px; }
.placeholder-board h2 { margin: 56px 0 10px; font-family: Georgia, "Times New Roman", serif; font-size: 32px; font-weight: 400; }
.placeholder-board p, .deferred-card p { max-width: 660px; color: var(--muted); }
.compact-heading { align-items: center; }
.phase-pill { padding: 10px 16px; border: 1px solid var(--line); border-radius: 999px; color: var(--blue-deep); font-size: 11px; font-weight: 700; letter-spacing: .12em; }
.deferred-card { display: grid; grid-template-columns: 84px 1fr; gap: 24px; min-height: 280px; padding: clamp(28px,5vw,58px); border-radius: 24px; }
.deferred-index { color: var(--coral); font-family: Georgia, "Times New Roman", serif; font-size: 60px; }
.deferred-card p:first-child { margin-top: 12px; color: var(--ink); font-family: Georgia, "Times New Roman", serif; font-size: clamp(24px,3vw,38px); line-height: 1.25; }
.muted-copy { margin-top: 30px; font-size: 14px; }
.today-board { display: grid; gap: 22px; }
.today-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 20px; }
.mode-switcher { display: flex; gap: 8px; padding: 5px; border: 1px solid var(--line); border-radius: 16px; background: rgba(255,253,247,.65); }
.mode-button { display: flex; align-items: baseline; gap: 8px; min-height: 44px; padding: 0 14px; border: 0; border-radius: 11px; background: transparent; color: var(--muted); cursor: pointer; }
.mode-button strong { font-family: Georgia, "Times New Roman", serif; font-size: 19px; }
.mode-button span { font-size: 11px; }
.mode-button.is-selected { background: var(--ink); color: var(--paper-strong); }
.save-indicator { display: flex; align-items: center; gap: 8px; color: var(--muted); font-size: 12px; }
.save-indicator.saved span { color: var(--sage); }
.save-indicator.unavailable span { color: var(--coral); }
.reshape-button { min-height: 40px; padding: 0 12px; border: 1px solid var(--ink); background: var(--acid); cursor: pointer; font-size: 9px; font-weight: 800; letter-spacing: .08em; }
.reshape-state { color: var(--muted); font-size: 9px; letter-spacing: .06em; }
.storage-warning { padding: 13px 16px; border: 1px solid rgba(223,125,104,.45); border-radius: 12px; background: rgba(223,125,104,.08); color: #7b4136; font-size: 13px; }
.progress-row { display: grid; grid-template-columns: 100px 1fr 42px; align-items: center; gap: 16px; color: var(--muted); font-size: 12px; }
.progress-row > div:first-child { display: flex; align-items: baseline; justify-content: space-between; }
.progress-row strong { color: var(--ink); }
.progress-track { height: 5px; overflow: hidden; border-radius: 999px; background: var(--line); }
.progress-track span { display: block; height: 100%; border-radius: inherit; background: var(--coral); transition: width 200ms ease; }
.task-list { display: grid; gap: 14px; }
.task-card { position: relative; display: grid; grid-template-columns: 56px 1fr 90px; align-items: center; gap: 22px; min-height: 150px; overflow: hidden; padding: 24px 26px 24px 20px; border: 1px solid var(--line); border-radius: 20px; background: rgba(255,253,247,.8); box-shadow: 0 8px 30px rgba(31,41,45,.045); }
.task-card::before { position: absolute; inset: 0 auto 0 0; width: 5px; content: ""; background: var(--blue); }
.task-card.accent-coral::before { background: var(--coral); }
.task-card.accent-sage::before { background: var(--sage); }
.task-card.is-done { opacity: .62; }
.task-check { display: grid; width: 48px; height: 48px; place-items: center; border: 1px solid var(--line); border-radius: 50%; background: var(--paper-strong); color: var(--blue-deep); cursor: pointer; font-family: Georgia, "Times New Roman", serif; }
.task-card.is-done .task-check { border-color: var(--ink); background: var(--ink); color: white; }
.task-copy > span { color: var(--blue-deep); font-size: 10px; font-weight: 800; letter-spacing: .16em; text-transform: uppercase; }
.task-copy h2 { margin: 7px 0 5px; font-family: Georgia, "Times New Roman", serif; font-size: clamp(21px,2.2vw,30px); font-weight: 400; }
.task-copy p { margin: 0; color: var(--muted); font-size: 13px; }
.task-open { display: inline-block; margin-top: 12px; border-bottom: 1px solid currentColor; color: var(--blue); font-size: 10px; font-weight: 800; letter-spacing: .08em; }
.task-meta { display: grid; justify-items: end; }
.task-meta strong { font-family: Georgia, "Times New Roman", serif; font-size: 34px; font-weight: 400; line-height: 1; }
.task-meta span { color: var(--muted); font-size: 9px; letter-spacing: .16em; }
.task-meta button { min-width: 58px; min-height: 34px; margin-top: 12px; border: 0; background: transparent; color: var(--blue-deep); cursor: pointer; font-size: 12px; text-decoration: underline; text-underline-offset: 3px; }
.exam-heading { margin-bottom: 28px; }
.exam-launch { display: grid; grid-template-columns: minmax(0,1.25fr) minmax(260px,.75fr); gap: 40px; min-height: 420px; padding: clamp(30px,5vw,62px); border: 1px solid var(--line); border-radius: 24px; background: rgba(255,253,247,.82); box-shadow: var(--shadow); }
.source-label { color: var(--coral); font-size: 11px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }
.exam-launch h2 { max-width: 620px; margin: 20px 0 8px; font-family: Georgia, "Times New Roman", serif; font-size: clamp(34px,4vw,58px); font-weight: 400; line-height: 1.05; }
.exam-launch p, .exam-launch li { color: var(--muted); }
.exam-launch ul { margin: 34px 0 0; padding-left: 20px; line-height: 2; }
.exam-launch-actions { display: flex; flex-direction: column; justify-content: center; gap: 12px; }
.exam-mode-picker { display: grid; grid-template-columns: 1fr 1fr; border: 1px solid var(--line); border-radius: 14px; overflow: hidden; }
.exam-mode-picker button { display: grid; gap: 6px; min-height: 106px; padding: 16px; border: 0; border-right: 1px solid var(--line); background: transparent; cursor: pointer; text-align: left; }
.exam-mode-picker button:last-child { border-right: 0; }
.exam-mode-picker button.is-active { background: var(--ink); color: white; }
.exam-mode-picker strong { font-size: 11px; letter-spacing: .1em; }
.exam-mode-picker span { color: var(--muted); font-size: 11px; line-height: 1.35; }
.exam-mode-picker button.is-active span { color: #d7dadb; }
.primary-action, .secondary-action { min-height: 52px; padding: 0 20px; border-radius: 12px; cursor: pointer; font-weight: 700; }
.primary-action { border: 1px solid var(--ink); background: var(--ink); color: white; }
.secondary-action { border: 1px solid var(--line); background: transparent; }
.primary-action:disabled, .secondary-action:disabled { cursor: not-allowed; opacity: .45; }
.storage-proof { min-height: 24px; margin: 6px 0 0; font-size: 12px; text-align: center; }
.storage-proof.ready { color: #55705a; }
.storage-proof.unavailable { color: #8b4236; }
.exam-shell { overflow: hidden; border: 1px solid #cbd0d2; border-radius: 16px; background: #fff; box-shadow: var(--shadow); }
.exam-bar { display: grid; grid-template-columns: minmax(0,1fr) auto auto auto; align-items: center; gap: 18px; min-height: 64px; padding: 10px 18px; border-bottom: 1px solid #dfe2e3; background: #f5f6f6; }
.exam-bar > div:first-child { display: grid; }
.exam-bar span { color: #667176; font-size: 9px; font-weight: 800; letter-spacing: .15em; }
.exam-bar strong { font-size: 13px; }
.exam-save { color: #55705a; font-size: 11px; }
.exam-save.saving { color: #8b6b35; }
.exam-save.unavailable { color: #8b4236; }
.exam-timer { min-width: 92px; padding: 8px 12px; border-radius: 8px; background: var(--ink); color: white; font-variant-numeric: tabular-nums; font-weight: 800; text-align: center; }
.exam-timer.is-low { background: #9a3d35; }
.exam-pause { min-height: 36px; padding: 0 13px; border: 1px solid var(--ink); border-radius: 8px; background: white; cursor: pointer; font-size: 9px; font-weight: 800; letter-spacing: .1em; }
.exam-split { display: grid; grid-template-columns: minmax(0,1fr) minmax(380px,.86fr); height: min(650px,70vh); }
.passage-pane, .question-pane { overflow: auto; padding: 34px clamp(24px,3vw,44px); }
.passage-pane { border-right: 1px solid #dfe2e3; background: #fbfbf9; }
.passage-title span { color: #6b7477; font-size: 10px; text-transform: uppercase; }
.passage-title h2 { margin: 8px 0 34px; font-family: Georgia, "Times New Roman", serif; font-size: 32px; font-weight: 400; }
.passage-paragraph { display: grid; grid-template-columns: 28px 1fr; gap: 10px; margin-bottom: 24px; }
.passage-paragraph strong { color: var(--blue-deep); font-family: Georgia, "Times New Roman", serif; }
.passage-paragraph p { margin: 0; color: #30383b; font-family: Georgia, "Times New Roman", serif; font-size: 16px; line-height: 1.78; }
.question-progress { display: flex; justify-content: space-between; color: #667176; font-size: 11px; }
.question-card { margin-top: 36px; }
.question-number { color: var(--coral); font-family: Georgia, "Times New Roman", serif; font-size: 36px; }
.question-card h2 { margin: 8px 0 28px; font-family: Georgia, "Times New Roman", serif; font-size: 25px; font-weight: 400; line-height: 1.3; }
.question-card fieldset { display: grid; gap: 10px; margin: 0; padding: 0; border: 0; }
.answer-option { display: grid; grid-template-columns: 20px 34px 1fr; align-items: center; gap: 10px; min-height: 58px; padding: 10px 14px; border: 1px solid #dfe2e3; border-radius: 10px; cursor: pointer; }
.answer-option:has(input:checked) { border-color: var(--blue); background: rgba(86,111,131,.08); }
.option-letter { display: grid; width: 30px; height: 30px; place-items: center; border-radius: 50%; background: #edf0f1; font-weight: 800; }
.short-answer { display: grid; gap: 8px; color: #667176; font-size: 11px; }
.short-answer input { width: 100%; min-height: 50px; padding: 0 14px; border: 1px solid #bfc5c7; border-radius: 8px; background: white; color: var(--ink); font-size: 15px; }
.exam-locked { margin-top: 22px; padding: 12px; border-radius: 8px; background: #f7eee8; color: #7b4136; font-size: 12px; }
.exam-footer { display: flex; align-items: center; justify-content: space-between; gap: 18px; min-height: 70px; padding: 10px 18px; border-top: 1px solid #dfe2e3; background: #f5f6f6; }
.question-nav { display: flex; gap: 7px; overflow-x: auto; }
.question-nav button { flex: 0 0 auto; width: 38px; height: 38px; border: 1px solid #cbd0d2; border-radius: 7px; background: white; cursor: pointer; font-weight: 700; }
.question-nav button.is-answered { border-bottom: 4px solid var(--sage); }
.question-nav button.is-current { border-color: var(--ink); background: var(--ink); color: white; }
.submit-test { min-width: 92px; min-height: 42px; border: 0; border-radius: 8px; background: var(--coral); color: white; cursor: pointer; font-weight: 800; }
.submit-test:disabled { opacity: .5; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; margin: -1px; padding: 0; border: 0; clip: rect(0,0,0,0); }
.library-heading { margin-bottom: 28px; }
.library-layout { display: grid; grid-template-columns: minmax(0,1fr) 340px; gap: 24px; align-items: start; }
.library-main { min-width: 0; }
.library-filters { display: grid; gap: 14px; }
.category-chips { display: flex; gap: 7px; overflow-x: auto; padding-bottom: 4px; }
.category-chips button { flex: 0 0 auto; min-height: 40px; padding: 0 15px; border: 1px solid var(--line); border-radius: 999px; background: rgba(255,253,247,.72); color: var(--muted); cursor: pointer; font-size: 12px; }
.category-chips button.is-active { border-color: var(--ink); background: var(--ink); color: white; }
.filter-row { display: grid; grid-template-columns: 1fr 100px 100px; gap: 8px; }
.filter-row input, .filter-row select { width: 100%; min-height: 44px; padding: 0 12px; border: 1px solid var(--line); border-radius: 10px; background: rgba(255,253,247,.8); }
.library-count { display: flex; justify-content: space-between; margin: 24px 2px 10px; color: var(--muted); font-size: 11px; }
.seed-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 12px; }
.seed-card { display: flex; flex-direction: column; min-height: 250px; padding: 20px; border: 1px solid var(--line); border-radius: 16px; background: rgba(255,253,247,.82); box-shadow: 0 8px 24px rgba(31,41,45,.04); }
.seed-top { display: flex; justify-content: space-between; color: var(--coral); font-family: Georgia, "Times New Roman", serif; font-size: 12px; }
.seed-card > div:nth-child(2) { margin-top: 28px; }
.seed-card p { margin: 0 0 7px; color: var(--blue-deep); font-size: 9px; font-weight: 800; letter-spacing: .14em; text-transform: uppercase; }
.seed-card h2 { margin: 0; font-family: Georgia, "Times New Roman", serif; font-size: 21px; font-weight: 400; line-height: 1.2; }
.publisher { color: var(--muted); font-size: 11px; }
.skill-list { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 18px; }
.skill-list span { padding: 4px 7px; border-radius: 5px; background: rgba(86,111,131,.08); color: var(--blue-deep); font-size: 9px; }
.seed-actions { display: flex; gap: 8px; margin-top: auto; padding-top: 18px; }
.seed-actions button { min-height: 38px; padding: 0 12px; border: 1px solid var(--line); border-radius: 8px; background: transparent; cursor: pointer; font-size: 11px; }
.seed-actions button:first-child { flex: 1; border-color: var(--ink); background: var(--ink); color: white; }
.seed-actions button.is-saved { color: #55705a; }
.activity-drawer { position: sticky; top: 28px; min-height: 520px; padding: 28px; border: 1px solid var(--line); border-radius: 18px; background: rgba(255,253,247,.92); box-shadow: var(--shadow); }
.drawer-close { position: absolute; top: 12px; right: 12px; display: grid; width: 40px; height: 40px; place-items: center; border: 0; background: transparent; cursor: pointer; font-size: 24px; }
.activity-drawer h2 { margin: 18px 0 4px; font-family: Georgia, "Times New Roman", serif; font-size: 30px; font-weight: 400; line-height: 1.12; }
.drawer-publisher { margin: 0 0 30px; color: var(--muted); font-size: 12px; }
.activity-step { display: grid; grid-template-columns: 30px 1fr; gap: 12px; margin: 22px 0; }
.activity-step > span { color: var(--coral); font-family: Georgia, "Times New Roman", serif; }
.activity-step strong { font-size: 12px; }
.activity-step p, .rights-note p { margin: 5px 0 0; color: var(--muted); font-size: 12px; line-height: 1.65; }
.rights-note { margin: 26px 0 20px; padding: 14px; border-radius: 10px; background: rgba(167,181,164,.13); }
.rights-note strong, .rights-note small { font-size: 10px; }
.rights-note small { display: block; margin-top: 8px; color: var(--muted); }
.source-action { display: grid; place-items: center; }
.activity-drawer .secondary-action { width: 100%; margin-top: 8px; }
.drawer-status { min-height: 18px; color: var(--muted); font-size: 10px; text-align: center; }
.drawer-empty { display: grid; min-height: 450px; place-content: center; text-align: center; }
.drawer-empty span { color: var(--coral); font-size: 58px; }
.drawer-empty p { max-width: 220px; color: var(--muted); font-family: Georgia, "Times New Roman", serif; font-size: 20px; }
.portfolio-heading { margin-bottom: 28px; }
.portfolio-workspace { display: grid; grid-template-columns: minmax(0,1.05fr) minmax(390px,.95fr); gap: 22px; align-items: start; }
.portfolio-editor, .walkthrough-preview { border: 1px solid var(--line); border-radius: 18px; background: rgba(255,253,247,.83); box-shadow: 0 12px 34px rgba(31,41,45,.05); }
.portfolio-editor { padding: 22px; }
.portfolio-status { display: grid; grid-template-columns: 100px 1fr auto; align-items: center; gap: 12px; margin-bottom: 18px; color: var(--muted); font-size: 10px; }
.portfolio-status > div:first-child { display: flex; justify-content: space-between; }
.portfolio-progress { height: 5px; overflow: hidden; border-radius: 999px; background: var(--line); }
.portfolio-progress span { display: block; height: 100%; background: var(--coral); }
.portfolio-fields { display: grid; gap: 10px; }
.portfolio-field { display: grid; grid-template-columns: 150px 1fr; gap: 14px; align-items: start; padding: 12px 0; border-top: 1px solid rgba(217,213,202,.7); }
.portfolio-field > span { display: flex; gap: 10px; padding-top: 9px; color: var(--blue-deep); font-size: 11px; font-weight: 700; }
.portfolio-field b { color: var(--coral); font-family: Georgia, "Times New Roman", serif; font-weight: 400; }
.portfolio-field textarea { width: 100%; resize: vertical; padding: 10px 12px; border: 1px solid transparent; border-radius: 8px; background: rgba(244,241,233,.8); font-size: 12px; line-height: 1.5; }
.portfolio-field textarea:focus { border-color: var(--blue); background: white; }
.walkthrough-preview { position: sticky; top: 28px; max-height: calc(100vh - 56px); overflow: auto; padding: 22px; }
.rehearsal-controls { display: grid; grid-template-columns: 1fr auto auto; align-items: center; gap: 12px; padding-bottom: 18px; border-bottom: 1px solid var(--line); }
.rehearsal-controls > div { display: flex; gap: 5px; }
.rehearsal-controls button { min-height: 38px; padding: 0 10px; border: 1px solid var(--line); border-radius: 8px; background: transparent; cursor: pointer; font-size: 10px; }
.rehearsal-controls button.is-active { border-color: var(--ink); background: var(--ink); color: white; }
.rehearsal-controls > strong { font-family: Georgia, "Times New Roman", serif; font-size: 24px; font-variant-numeric: tabular-nums; }
.rehearsal-controls .rehearse-button { border-color: var(--coral); background: var(--coral); color: white; }
.outline-list { display: grid; margin-top: 12px; }
.outline-list article { display: grid; grid-template-columns: 34px 1fr; gap: 10px; padding: 14px 0; border-bottom: 1px solid rgba(217,213,202,.7); }
.outline-list article > span { color: var(--coral); font-family: Georgia, "Times New Roman", serif; }
.outline-list p { margin: 0 0 3px; color: var(--blue-deep); font-size: 9px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }
.outline-list strong, .outline-list small { display: block; }
.outline-list strong { font-family: Georgia, "Times New Roman", serif; font-size: 15px; font-weight: 400; }
.outline-list small { margin-top: 5px; color: var(--muted); font-size: 11px; }
.reflection-box { display: grid; gap: 12px; margin-top: 20px; padding: 16px; border-radius: 10px; background: rgba(86,111,131,.07); }
.reflection-box label { display: grid; gap: 6px; }
.reflection-box span { color: var(--blue-deep); font-size: 10px; font-weight: 700; }
.reflection-box textarea, .reflection-box input { width: 100%; padding: 9px 10px; border: 1px solid var(--line); border-radius: 7px; background: white; font-size: 11px; }

@media (max-width: 900px) {
  .app-frame { display: block; }
  .side-rail { position: static; display: grid; grid-template-columns: 1fr auto; height: auto; padding: 16px 20px 10px; border-right: 0; border-bottom: 1px solid var(--line); }
  .main-nav { grid-column: 1 / -1; display: flex; gap: 6px; margin-top: 12px; overflow-x: auto; padding-bottom: 6px; }
  .nav-link { display: flex; flex: 0 0 auto; gap: 8px; padding: 0 14px; }
  .account-card { grid-template-columns: 38px 28px; margin: 0; padding: 0; border: 0; }
  .account-copy { display: none; }
  .main-canvas { padding-top: 32px; }
  .exam-split { grid-template-columns: 1fr; height: auto; }
  .passage-pane { max-height: 480px; border-right: 0; border-bottom: 1px solid #dfe2e3; }
  .question-pane { min-height: 430px; }
  .library-layout { grid-template-columns: 1fr; }
  .activity-drawer { position: static; min-height: 0; }
  .portfolio-workspace { grid-template-columns: 1fr; }
  .walkthrough-preview { position: static; max-height: none; }
}

@media (max-width: 640px) {
  .brand strong { font-size: 13px; }
  .brand-orbit { width: 32px; height: 32px; }
  .page-heading { display: grid; margin-bottom: 26px; }
  .page-heading h1 { font-size: 44px; }
  .script-line { justify-self: end; }
  .deferred-card { grid-template-columns: 1fr; }
  .deferred-index { font-size: 42px; }
  .today-toolbar { align-items: stretch; flex-direction: column; }
  .mode-switcher { width: 100%; }
  .mode-button { flex: 1; justify-content: center; padding: 0 8px; }
  .mode-button span { display: none; }
  .progress-row { grid-template-columns: 84px 1fr 36px; }
  .task-card { grid-template-columns: 48px 1fr; gap: 14px; padding: 20px 18px 20px 15px; }
  .task-meta { grid-column: 2; grid-row: 2; display: flex; align-items: baseline; justify-content: flex-start; gap: 6px; }
  .task-meta strong { font-size: 24px; }
  .task-meta button { margin: 0 0 0 auto; }
  .exam-launch { grid-template-columns: 1fr; }
  .exam-bar { grid-template-columns: 1fr auto; }
  .exam-save { display: none; }
  .exam-footer { align-items: stretch; flex-direction: column; }
  .submit-test { width: 100%; }
  .filter-row { grid-template-columns: 1fr 86px 86px; }
  .seed-grid { grid-template-columns: 1fr; }
  .portfolio-field { grid-template-columns: 1fr; gap: 4px; }
  .rehearsal-controls { grid-template-columns: 1fr auto; }
  .rehearsal-controls .rehearse-button { grid-column: 1 / -1; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; }
}

/* Phase 2 editorial system */
:root {
  --paper: #fafafa;
  --paper-strong: #ffffff;
  --ink: #121416;
  --muted: #666666;
  --line: #d8d8d8;
  --blue: #153cff;
  --blue-deep: #153cff;
  --coral: #ff4d23;
  --sage: #d9f238;
  --acid: #d9f238;
  --shadow: none;
}

html { background: var(--paper); }
body {
  background: var(--paper);
  font-family: Arial, Helvetica, sans-serif;
}

.editorial-frame.app-frame { display: block; min-height: 100vh; }
.site-masthead {
  position: relative;
  z-index: 10;
  border-bottom: 1px solid var(--ink);
  background: var(--paper);
}
.masthead-line {
  display: grid;
  grid-template-columns: minmax(240px, 1fr) auto minmax(180px, 1fr);
  align-items: stretch;
  min-height: 88px;
  border-bottom: 1px solid var(--ink);
}
.brand {
  display: grid;
  align-content: center;
  gap: 2px;
  min-height: 0;
  padding: 15px clamp(18px, 3vw, 44px);
  border-right: 1px solid var(--ink);
  letter-spacing: 0;
}
.brand strong {
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(21px, 2.2vw, 32px);
  font-weight: 400;
  letter-spacing: -.04em;
}
.brand span { color: var(--muted); font-size: 9px; letter-spacing: .12em; text-transform: uppercase; }
.issue-stamp {
  display: grid;
  align-content: center;
  gap: 3px;
  min-width: 170px;
  padding: 14px 28px;
  border-right: 1px solid var(--ink);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .14em;
}
.issue-stamp span:last-child { color: var(--muted); font-weight: 500; }
.archive-corner {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding: 14px clamp(18px, 3vw, 44px);
  color: var(--blue);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .1em;
}
.main-nav {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 0;
  margin: 0;
  overflow-x: auto;
}
.nav-link {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 9px;
  min-height: 43px;
  padding: 0 13px;
  border-right: 1px solid var(--line);
  border-radius: 0;
  color: var(--ink);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  transition: background 140ms ease, color 140ms ease;
}
.nav-link:hover { color: var(--ink); transform: none; background: var(--acid); }
.nav-link.is-active { background: var(--ink); color: var(--paper); }
.nav-mark { color: inherit; font-family: Arial, Helvetica, sans-serif; font-size: 8px; opacity: .55; }

.main-canvas { width: 100%; max-width: none; padding: 0; }
.issue-home { width: 100%; }
.issue-hero {
  display: grid;
  grid-template-columns: minmax(360px, 1.04fr) minmax(360px, 1.2fr) minmax(92px, .28fr);
  min-height: 650px;
  border-bottom: 1px solid var(--ink);
}
.issue-title-block { display: flex; flex-direction: column; padding: clamp(28px, 5vw, 76px) clamp(22px, 4vw, 64px) 40px; }
.issue-kicker { display: flex; justify-content: space-between; margin: 0 0 auto; font-size: 9px; font-weight: 800; letter-spacing: .12em; }
.issue-title-block h1 {
  margin: 54px 0 24px;
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(82px, 10.5vw, 172px);
  font-weight: 400;
  letter-spacing: -.085em;
  line-height: .7;
}
.issue-deck { max-width: 560px; margin: 24px 0 30px; font-family: Georgia, "Times New Roman", serif; font-size: clamp(18px, 1.55vw, 25px); line-height: 1.25; }
