}

@media (max-width: 640px) {
  .vocabulary-shelf-heading { align-items: flex-start; }
  .vocabulary-shelf-heading-actions { align-items: flex-end; flex-direction: column-reverse; gap: 7px; }
  .vocabulary-shelf-heading-actions > strong { min-width: 0; }
  .vocabulary-shelf-item { grid-template-columns: 28px 1fr; gap: 8px 10px; }
  .vocabulary-term, .vocabulary-meaning, .vocabulary-definition, .vocabulary-item-actions { grid-column: 2; }
